{
  "title": "The Shattered Crown Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party arrives at the ruined city gates.",
      "visual_description": "Massive iron gates lie half-buckled, overgrown with thorny vines; a cracked royal crest looms above.",
      "characters": ["Lyra", "Kael", "Mira"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople whisper warnings.",
      "visual_description": "Huddled in rags behind a broken wall, a mother clutches her child as she points toward the central tower.",
      "characters": ["Jessa", "Tomas"]
    },
    {
      "scene_number": 3,
      "caption": "They skirt a cursed tower that glows with pale light.",
      "visual_description": "A spiral tower emits a sickly green luminescence; faint whispers echo from its shuttered windows.",
      "characters": ["Lyra", "Kael", "Mira"]
    },
    {
      "scene_number": 4,
      "caption": "Old royal banners stir in the wind.",
      "visual_description": "Tattered banners bearing a golden phoenix snap on a broken flagpole above a courtyard of rubble.",
      "characters": ["Kael"]
    },
    {
      "scene_number": 5,
      "caption": "Armored patrols march through the market square.",
      "visual_description": "Six guards in blackened plate armor, their visors down, carry torches that cast long shadows.",
      "characters": ["Guard_Captain", "Guard_1", "Guard_2"]
    },
    {
      "scene_number": 6,
      "caption": "The party hides in a collapsed temple.",
      "visual_description": "A toppled statue of a winged goddess lies amid shattered pews; moonlight filters through a broken dome.",
      "characters": ["Lyra", "Kael", "Mira"]
    },
    {
      "scene_number": 7,
      "caption": "Mira picks a magic door with a singing lock.",
      "visual_description": "A silver door inscribed with runes hums as Mira’s lockpicks glow; the runes shift from blue to red.",
      "characters": ["Mira"]
    },
    {
      "scene_number": 8,
      "caption": "They step into the Throne Room of Whispers.",
      "visual_description": "A vast hall with a crumbling throne; spectral echoes of past coronations flicker in the air.",
      "characters": ["Lyra", "Kael", "Mira"]
    },
    {
      "scene_number": 9,
      "caption": "A dragon’s shadow passes overhead—just a rumor made real.",
      "visual_description": "A massive winged silhouette blocks the moon for a second; the roar shakes dust from the ceiling.",
      "characters": ["Lyra", "Kael", "Mira"]
    },
    {
      "scene_number": 10,
      "caption": "They descend into the dungeon to find the prisoner.",
      "visual_description": "Dark stone stairs slick with moisture; a single torch at the bottom reveals a cell door.",
      "characters": ["Lyra", "Kael", "Mira"]
    },
    {
      "scene_number": 11,
      "caption": "The prisoner is chained to the wall, barely alive.",
      "visual_description": "A gaunt figure in tattered robes, iron manacles around wrists, eyes sunken but alert.",
      "characters": ["Eldric"]
    },
    {
      "scene_number": 12,
      "caption": "Kael breaks the chains with a forged key.",
      "visual_description": "Sparks fly as the ornate key turns in the lock; the manacles fall with a clang.",
      "characters": ["Kael", "Eldric"]
    },
    {
      "scene_number": 13,
      "caption": "A magical alarm triggers: the doors seal.",
      "visual_description": "Blue energy bars slide across every exit; the walls begin to pulse with light.",
      "characters": ["Lyra", "Kael", "Mira", "Eldric"]
    },
    {
      "scene_number": 14,
      "caption": "Lyra dispels the barrier with a counter-rune.",
      "visual_description": "She draws a glowing symbol in the air; the energy bars shatter like glass.",
      "characters": ["Lyra"]
    },
    {
      "scene_number": 15,
      "caption": "Guards swarm the corridor ahead.",
      "visual_description": "At least a dozen guards with crossbows form a wall; the captain shouts orders.",
      "characters": ["Guard_Captain", "Guard_1", "Guard_2", "Guard_3"]
    },
    {
      "scene_number": 16,
      "caption": "Mira throws a smoke bomb and they dash past.",
      "visual_description": "A thick gray cloud fills the hall; coughing guards wave their arms as the party runs through.",
      "characters": ["Mira", "Lyra", "Kael", "Eldric"]
    },
    {
      "scene_number": 17,
      "caption": "They burst out onto the escape bridge.",
      "visual_description": "A narrow stone bridge spans a chasm; the far gate stands open under a red dawn sky.",
      "characters": ["Lyra", "Kael", "Mira", "Eldric"]
    },
    {
      "scene_number": 18,
      "caption": "The bridge collapses behind them as they cross.",
      "visual_description": "Stones tumble into the abyss; the party stumbles onto safe ground as the last block falls.",
      "characters": ["Lyra", "Kael", "Mira", "Eldric"]
    }
  ]
}

